INSERT INTO skills (code, subject_code, name) VALUES
    ('EXPONENTS_G6', 'MATH', 'Exponents'),
    ('GREEK_LATIN_ROOTS', 'ENGLISH', 'Greek and Latin Roots');
INSERT INTO lessons (id, code, subject_code, grade_level, display_order, title, description) VALUES
    ('17000000-0000-0000-0000-000000000018', 'G6-EXPONENT-01', 'MATH', 'GRADE_6', 10, 'Exponents', 'Use exponents to show repeated multiplication.'),
    ('17000000-0000-0000-0000-000000000019', 'G6-ENG-ROOTS-01', 'ENGLISH', 'GRADE_6', 9, 'Greek and Latin Roots', 'Unlock new words using roots like bio, tele, and port.');
INSERT INTO exercises (id, lesson_code, skill_code, display_order, prompt, answer_index, explanation, hint) VALUES
    ('37000000-0000-0000-0000-000000000001', 'G6-RATIO-01', 'RATIOS_RATES', 4, 'A bag has 4 apples and 10 oranges. What is the ratio of apples to oranges in simplest form?', 0, '4:10 simplifies by dividing both by 2: 2:5.', 'Divide both numbers by the same factor.'),
    ('37000000-0000-0000-0000-000000000002', 'G6-RATIO-01', 'RATIOS_RATES', 5, 'You type 180 words in 3 minutes. What is your rate per minute?', 1, '180 / 3 = 60 words per minute.', 'Divide by the time.'),
    ('37000000-0000-0000-0000-000000000003', 'G6-RATIO-01', 'RATIOS_RATES', 6, 'Which ratio is equivalent to 3:4?', 1, 'Multiply both by 3: 9:12.', 'Multiply both numbers by the same thing.'),
    ('37000000-0000-0000-0000-000000000004', 'G6-PERCENT-01', 'PERCENT_G6', 4, 'What is 15% of 200?', 0, '10% of 200 = 20 and 5% = 10, so 30.', 'Split into 10% + 5%.'),
    ('37000000-0000-0000-0000-000000000005', 'G6-PERCENT-01', 'PERCENT_G6', 5, 'What percent is 9 out of 36?', 0, '9/36 = 1/4 = 25%.', 'Simplify the fraction.'),
    ('37000000-0000-0000-0000-000000000006', 'G6-PERCENT-01', 'PERCENT_G6', 6, '30 is 50% of what number?', 2, 'If half is 30, the whole is 60.', '50% means half.'),
    ('37000000-0000-0000-0000-000000000007', 'G6-NEGNUM-01', 'NEGATIVE_NUM', 4, 'What is -7 + 10?', 1, 'Start at -7 and move 10 right: 3.', 'Use a number line.'),
    ('37000000-0000-0000-0000-000000000008', 'G6-NEGNUM-01', 'NEGATIVE_NUM', 5, 'What is 2 - 9?', 1, '2 - 9 = -7.', 'You go past zero.'),
    ('37000000-0000-0000-0000-000000000009', 'G6-NEGNUM-01', 'NEGATIVE_NUM', 6, 'What is (-3) x 4?', 0, 'Negative times positive is negative: -12.', 'Signs: different means negative.'),
    ('37000000-0000-0000-0000-000000000010', 'G6-ALGEBRA-01', 'ALGEBRA_EXPR', 4, 'If n = 6, what is 3n - 4?', 2, '3 x 6 = 18, then 18 - 4 = 14.', 'Multiply first, then subtract.'),
    ('37000000-0000-0000-0000-000000000011', 'G6-ALGEBRA-01', 'ALGEBRA_EXPR', 5, 'Which expression means "5 more than x"?', 0, '"More than" means add.', 'More than means add.'),
    ('37000000-0000-0000-0000-000000000012', 'G6-ALGEBRA-01', 'ALGEBRA_EXPR', 6, 'Simplify: 2a + 3a.', 0, 'Combine like terms: 2a + 3a = 5a.', 'Add the numbers in front.'),
    ('37000000-0000-0000-0000-000000000013', 'G6-ONESTEP-01', 'ONE_STEP_EQ', 4, 'Solve for x: x / 4 = 3.', 0, 'Multiply both sides by 4: x = 12.', 'Undo division with multiplication.'),
    ('37000000-0000-0000-0000-000000000014', 'G6-ONESTEP-01', 'ONE_STEP_EQ', 5, 'Solve for y: y + 9 = 15.', 1, 'Subtract 9 from both sides: y = 6.', 'Undo adding with subtracting.'),
    ('37000000-0000-0000-0000-000000000015', 'G6-ONESTEP-01', 'ONE_STEP_EQ', 6, 'Solve for m: 5m = 45.', 1, 'Divide both sides by 5: m = 9.', 'Undo multiplying with dividing.'),
    ('37000000-0000-0000-0000-000000000016', 'G6-STATS-01', 'STATISTICS_BASIC', 4, 'What is the range of 3, 8, 12, 5?', 2, 'Range = largest - smallest = 12 - 3 = 9.', 'Biggest minus smallest.'),
    ('37000000-0000-0000-0000-000000000017', 'G6-STATS-01', 'STATISTICS_BASIC', 5, 'What is the median of 4, 8, 6, 2?', 0, 'Order: 2, 4, 6, 8. Middle two: (4 + 6) / 2 = 5.', 'Order the numbers first.'),
    ('37000000-0000-0000-0000-000000000018', 'G6-STATS-01', 'STATISTICS_BASIC', 6, 'What is the mean of 10, 20, 30, 40?', 2, 'Sum = 100, divided by 4 = 25.', 'Add them up and divide by how many.'),
    ('37000000-0000-0000-0000-000000000019', 'G6-AREACOMPLEX-01', 'AREA_COMPLEX', 4, 'A triangle has a base of 10 and a height of 5. What is its area?', 2, '1/2 x 10 x 5 = 25.', 'Half of base times height.'),
    ('37000000-0000-0000-0000-000000000020', 'G6-AREACOMPLEX-01', 'AREA_COMPLEX', 5, 'A parallelogram has a base of 8 and a height of 3. What is its area?', 2, 'Area = base x height = 24.', 'Base times height.'),
    ('37000000-0000-0000-0000-000000000021', 'G6-AREACOMPLEX-01', 'AREA_COMPLEX', 6, 'A 6x6 square has a 2x2 square cut out of it. What area is left?', 1, '36 - 4 = 32.', 'Subtract the missing part.'),
    ('37000000-0000-0000-0000-000000000022', 'G6-COORDGEO-01', 'COORD_GEOMETRY', 4, 'Which quadrant is the point (-2,-5) in?', 1, 'Both coordinates are negative: Quadrant III.', 'Negative x and negative y.'),
    ('37000000-0000-0000-0000-000000000023', 'G6-COORDGEO-01', 'COORD_GEOMETRY', 5, 'What is the distance between the points (-3,2) and (4,2)?', 1, 'Same y, so distance = 4 - (-3) = 7.', 'Count across zero.'),
    ('37000000-0000-0000-0000-000000000024', 'G6-COORDGEO-01', 'COORD_GEOMETRY', 6, 'Reflect the point (5,3) across the x-axis. Where does it land?', 2, 'Reflecting over the x-axis flips the sign of y.', 'Over the x-axis, y changes sign.'),
    ('37000000-0000-0000-0000-000000000025', 'G6-WORD-01', 'WORD_PROB_G6', 4, 'A $25 game is on sale for 20% off. What is the sale price?', 0, '20% of 25 is 5, so 25 - 5 = 20.', 'Find the discount first.'),
    ('37000000-0000-0000-0000-000000000026', 'G6-WORD-01', 'WORD_PROB_G6', 5, 'A recipe uses 3 eggs for 12 cookies. How many eggs for 36 cookies?', 2, '36 is 3 times 12, so 3 x 3 = 9 eggs.', 'Scale up the ratio.'),
    ('37000000-0000-0000-0000-000000000027', 'G6-WORD-01', 'WORD_PROB_G6', 6, 'A class of 25 students has 60% girls. How many girls are there?', 0, '60% of 25 = 0.6 x 25 = 15.', 'Find 10% first, then times 6.'),
    ('37000000-0000-0000-0000-000000000028', 'G6-ENG-COMP-01', 'COMPREHENSION_G6', 4, 'Read: "Though the inventor''s first hundred designs failed, each one taught her something new." What is the author suggesting?', 0, 'Each failure taught her something.', 'What came from each failure?'),
    ('37000000-0000-0000-0000-000000000029', 'G6-ENG-COMP-01', 'COMPREHENSION_G6', 5, 'Read: "The documentary presented only the factory''s profits, never mentioning the polluted river nearby." What does this suggest?', 2, 'It left out important negative information.', 'What was missing?'),
    ('37000000-0000-0000-0000-000000000030', 'G6-ENG-COMP-01', 'COMPREHENSION_G6', 6, 'Read: "Sales of umbrellas tripled during the rainiest month on record." What relationship is shown?', 1, 'The rain caused umbrella sales to rise.', 'What caused what?'),
    ('37000000-0000-0000-0000-000000000031', 'G6-ENG-LITDEVICE-01', 'LITERARY_DEVICES', 4, '"The stars danced in the night sky" uses what device?', 1, 'Stars can''t dance, so they are given a human action.', 'Who usually dances?'),
    ('37000000-0000-0000-0000-000000000032', 'G6-ENG-LITDEVICE-01', 'LITERARY_DEVICES', 5, 'A story that hints at something that will happen later is using:', 2, 'Foreshadowing gives clues about the future.', 'Fore means before.'),
    ('37000000-0000-0000-0000-000000000033', 'G6-ENG-LITDEVICE-01', 'LITERARY_DEVICES', 6, 'A fire station burning down is an example of:', 0, 'It''s the opposite of what you''d expect.', 'Is it unexpected?'),
    ('37000000-0000-0000-0000-000000000034', 'G6-ENG-ARGUMENT-01', 'ARGUMENT_EVIDENCE', 4, 'What is a "counterclaim"?', 1, 'A counterclaim argues the other side.', 'Counter means against.'),
    ('37000000-0000-0000-0000-000000000035', 'G6-ENG-ARGUMENT-01', 'ARGUMENT_EVIDENCE', 5, 'Which is the weakest evidence?', 0, '"Everyone knows" offers no proof.', 'Which one has no real support?'),
    ('37000000-0000-0000-0000-000000000036', 'G6-ENG-ARGUMENT-01', 'ARGUMENT_EVIDENCE', 6, 'Why should a writer address counterclaims?', 2, 'Answering the other side makes an argument more convincing.', 'Does it strengthen the case?'),
    ('37000000-0000-0000-0000-000000000037', 'G6-ENG-COMPLEXSENT-01', 'COMPLEX_SENTENCES', 4, 'Which sentence is compound?', 0, 'Two independent clauses joined by "and".', 'Two sentences joined by and, but, or.'),
    ('37000000-0000-0000-0000-000000000038', 'G6-ENG-COMPLEXSENT-01', 'COMPLEX_SENTENCES', 5, 'Which word joins two independent clauses?', 1, '"But" is a coordinating conjunction.', 'FANBOYS: for, and, nor, but, or, yet, so.'),
    ('37000000-0000-0000-0000-000000000039', 'G6-ENG-COMPLEXSENT-01', 'COMPLEX_SENTENCES', 6, 'Which sentence is complex?', 1, '"When the sun set" is a dependent clause.', 'Look for a clause that can''t stand alone.'),
    ('37000000-0000-0000-0000-000000000040', 'G6-ENG-VOCAB-01', 'VOCAB_G6', 4, 'What does "infer" mean?', 1, 'Inferring means reasoning from clues.', 'Reading between the lines.'),
    ('37000000-0000-0000-0000-000000000041', 'G6-ENG-VOCAB-01', 'VOCAB_G6', 5, 'What does "contrast" mean?', 2, 'Contrasting points out differences.', 'The opposite of compare.'),
    ('37000000-0000-0000-0000-000000000042', 'G6-ENG-VOCAB-01', 'VOCAB_G6', 6, 'What does "cite" mean?', 1, 'You cite sources to show where facts came from.', 'Think of citations.'),
    ('37000000-0000-0000-0000-000000000043', 'G6-ENG-TEXTANALYSIS-01', 'TEXT_ANALYSIS', 4, 'What is "mood" in a story?', 0, 'Mood is the atmosphere created for the reader.', 'How does it make you feel?'),
    ('37000000-0000-0000-0000-000000000044', 'G6-ENG-TEXTANALYSIS-01', 'TEXT_ANALYSIS', 5, 'An author describes a stormy, dark night with creaking doors. What mood is created?', 2, 'Dark storms and creaks build tension.', 'How would you feel there?'),
    ('37000000-0000-0000-0000-000000000045', 'G6-ENG-TEXTANALYSIS-01', 'TEXT_ANALYSIS', 6, 'Why might an author use a flashback?', 1, 'A flashback reveals earlier events.', 'Flash back in time.'),
    ('37000000-0000-0000-0000-000000000046', 'G6-ENG-RESEARCH-01', 'RESEARCH_SKILLS', 4, 'Which website ending is usually a government source?', 0, '.gov sites belong to governments.', 'Gov for government.'),
    ('37000000-0000-0000-0000-000000000047', 'G6-ENG-RESEARCH-01', 'RESEARCH_SKILLS', 5, 'What is a primary source?', 2, 'Primary sources come directly from the time or person.', 'Who was there?'),
    ('37000000-0000-0000-0000-000000000048', 'G6-ENG-RESEARCH-01', 'RESEARCH_SKILLS', 6, 'What is plagiarism?', 0, 'Plagiarism is copying without credit.', 'It''s like stealing words.'),
    ('37000000-0000-0000-0000-000000000049', 'G6-ENG-PARAPHRASE-01', 'SUMMARIZE_PARAPHRASE', 4, 'Which is the best paraphrase of "The storm caused widespread damage"?', 2, 'It keeps the meaning in new words.', 'Same meaning, new words.'),
    ('37000000-0000-0000-0000-000000000050', 'G6-ENG-PARAPHRASE-01', 'SUMMARIZE_PARAPHRASE', 5, 'When paraphrasing, you should:', 0, 'A paraphrase changes words, not meaning.', 'What must stay the same?'),
    ('37000000-0000-0000-0000-000000000051', 'G6-ENG-PARAPHRASE-01', 'SUMMARIZE_PARAPHRASE', 6, 'How is a summary different from a paraphrase?', 1, 'Paraphrases can be the same length; summaries are shorter.', 'Which one shortens?'),
    ('37000000-0000-0000-0000-000000000052', 'G6-EXPONENT-01', 'EXPONENTS_G6', 1, 'What is 2 to the 3rd power (2 x 2 x 2)?', 2, '2 x 2 x 2 = 8.', 'Multiply 2 by itself 3 times.'),
    ('37000000-0000-0000-0000-000000000053', 'G6-EXPONENT-01', 'EXPONENTS_G6', 2, 'What is 5 squared?', 2, '5 squared = 5 x 5 = 25.', 'Squared means times itself.'),
    ('37000000-0000-0000-0000-000000000054', 'G6-EXPONENT-01', 'EXPONENTS_G6', 3, 'What is 10 cubed?', 1, '10 x 10 x 10 = 1000.', 'Cubed means three times.'),
    ('37000000-0000-0000-0000-000000000055', 'G6-EXPONENT-01', 'EXPONENTS_G6', 4, 'Which means 3 x 3 x 3 x 3?', 2, '3 used 4 times is 3 to the 4th.', 'The base is the number multiplied.'),
    ('37000000-0000-0000-0000-000000000056', 'G6-EXPONENT-01', 'EXPONENTS_G6', 5, 'What is any number (except 0) to the power of 0?', 1, 'Any nonzero number to the 0 power equals 1.', 'It''s a special rule.'),
    ('37000000-0000-0000-0000-000000000057', 'G6-EXPONENT-01', 'EXPONENTS_G6', 6, 'What is 4 squared minus 6?', 2, '4 x 4 = 16, then 16 - 6 = 10.', 'Exponents come before subtraction.'),
    ('37000000-0000-0000-0000-000000000058', 'G6-ENG-ROOTS-01', 'GREEK_LATIN_ROOTS', 1, 'The root "bio" means "life." What is biology?', 2, 'Bio (life) + logy (study) = study of life.', '-ology means study of.'),
    ('37000000-0000-0000-0000-000000000059', 'G6-ENG-ROOTS-01', 'GREEK_LATIN_ROOTS', 2, 'The root "tele" means "far." Which word means seeing far away?', 1, 'Tele (far) + scope (see) = telescope.', 'Scope means see.'),
    ('37000000-0000-0000-0000-000000000060', 'G6-ENG-ROOTS-01', 'GREEK_LATIN_ROOTS', 3, 'The root "port" means "carry." What does "portable" mean?', 2, 'Port (carry) + able = can be carried.', '-able means can be.'),
    ('37000000-0000-0000-0000-000000000061', 'G6-ENG-ROOTS-01', 'GREEK_LATIN_ROOTS', 4, 'The root "geo" means "earth." What does a geologist study?', 0, 'Geo (earth) + logist (one who studies).', 'Geo is earth.'),
    ('37000000-0000-0000-0000-000000000062', 'G6-ENG-ROOTS-01', 'GREEK_LATIN_ROOTS', 5, 'The root "chron" means "time." What is a chronological order?', 0, 'Chronological means arranged by time.', 'Chron is time.'),
    ('37000000-0000-0000-0000-000000000063', 'G6-ENG-ROOTS-01', 'GREEK_LATIN_ROOTS', 6, 'The root "aud" means "hear." Which word relates to hearing?', 0, 'An audience hears a performance.', 'Aud is hear.');
